        impl < T : ? Sized > ShardedLock < T > { # [doc = " Returns `true` if the lock is poisoned."] # [doc = ""] # [doc = " If another thread can still access the lock, it may become poisoned at any time. A `false`"] # [doc = " result should not be trusted without additional synchronization."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use crossbeam_utils::sync::ShardedLock;"] # [doc = " use std::sync::Arc;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let lock = Arc::new(ShardedLock::new(0));"] # [doc = " let c_lock = lock.clone();"] # [doc = ""] # [doc = " let _: Result<(), _> = thread::spawn(move || {"] # [doc = "     let _lock = c_lock.write().unwrap();"] # [doc = "     panic!(); // the lock gets poisoned"] # [doc = " }).join();"] # [doc = " assert_eq!(lock.is_poisoned(), true);"] # [doc = " ```"] pub fn is_poisoned (& self) -> bool { self . shards [0] . lock . is_poisoned () } # [doc = " Returns a mutable reference to the underlying data."] # [doc = ""] # [doc = " Since this call borrows the lock mutably, no actual locking needs to take place."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method will return an error if the lock is poisoned. A lock gets poisoned when a write"] # [doc = " operation panics."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use crossbeam_utils::sync::ShardedLock;"] # [doc = ""] # [doc = " let mut lock = ShardedLock::new(0);"] # [doc = " *lock.get_mut().unwrap() = 10;"] # [doc = " assert_eq!(*lock.read().unwrap(), 10);"] # [doc = " ```"] pub fn get_mut (& mut self) -> LockResult < & mut T > { let is_poisoned = self . is_poisoned () ; let inner = unsafe { & mut * self . value . get () } ; if is_poisoned { Err (PoisonError :: new (inner)) } else { Ok (inner) } } # [doc = " Attempts to acquire this lock with shared read access."] # [doc = ""] # [doc = " If the access could not be granted at this time, an error is returned. Otherwise, a guard"] # [doc = " is returned which will release the shared access when it is dropped. This method does not"] # [doc = " provide any guarantees with respect to the ordering of whether contentious readers or"] # [doc = " writers will acquire the lock first."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method will return an error if the lock is poisoned. A lock gets poisoned when a write"] # [doc = " operation panics."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use crossbeam_utils::sync::ShardedLock;"] # [doc = ""] # [doc = " let lock = ShardedLock::new(1);"] # [doc = ""] # [doc = " match lock.try_read() {"] # [doc = "     Ok(n) => assert_eq!(*n, 1),"] # [doc = "     Err(_) => unreachable!(),"] # [doc = " };"] # [doc = " ```"] pub fn try_read (& self) -> TryLockResult < ShardedLockReadGuard < '_ , T > > { let current_index = current_index () . unwrap_or (0) ; let shard_index = current_index & (self . shards . len () - 1) ; match self . shards [shard_index] . lock . try_read () { Ok (guard) => Ok (ShardedLockReadGuard { lock : self , _guard : guard , _marker : PhantomData , }) , Err (TryLockError :: Poisoned (err)) => { let guard = ShardedLockReadGuard { lock : self , _guard : err . into_inner () , _marker : PhantomData , } ; Err (TryLockError :: Poisoned (PoisonError :: new (guard))) } Err (TryLockError :: WouldBlock) => Err (TryLockError :: WouldBlock) , } } # [doc = " Locks with shared read access, blocking the current thread until it can be acquired."] # [doc = ""] # [doc = " The calling thread will be blocked until there are no more writers which hold the lock."] # [doc = " There may be other readers currently inside the lock when this method returns. This method"] # [doc = " does not provide any guarantees with respect to the ordering of whether contentious readers"] # [doc = " or writers will acquire the lock first."] # [doc = ""] # [doc = " Returns a guard which will release the shared access when dropped."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method will return an error if the lock is poisoned. A lock gets poisoned when a write"] # [doc = " operation panics."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This method might panic when called if the lock is already held by the current thread."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use crossbeam_utils::sync::ShardedLock;"] # [doc = " use std::sync::Arc;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " let lock = Arc::new(ShardedLock::new(1));"] # [doc = " let c_lock = lock.clone();"] # [doc = ""] # [doc = " let n = lock.read().unwrap();"] # [doc = " assert_eq!(*n, 1);"] # [doc = ""] # [doc = " thread::spawn(move || {"] # [doc = "     let r = c_lock.read();"] # [doc = "     assert!(r.is_ok());"] # [doc = " }).join().unwrap();"] # [doc = " ```"] pub fn read (& self) -> LockResult < ShardedLockReadGuard < '_ , T > > { let current_index = current_index () . unwrap_or (0) ; let shard_index = current_index & (self . shards . len () - 1) ; match self . shards [shard_index] . lock . read () { Ok (guard) => Ok (ShardedLockReadGuard { lock : self , _guard : guard , _marker : PhantomData , }) , Err (err) => Err (PoisonError :: new (ShardedLockReadGuard { lock : self , _guard : err . into_inner () , _marker : PhantomData , })) , } } # [doc = " Attempts to acquire this lock with exclusive write access."] # [doc = ""] # [doc = " If the access could not be granted at this time, an error is returned. Otherwise, a guard"] # [doc = " is returned which will release the exclusive access when it is dropped. This method does"] # [doc = " not provide any guarantees with respect to the ordering of whether contentious readers or"] # [doc = " writers will acquire the lock first."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method will return an error if the lock is poisoned. A lock gets poisoned when a write"] # [doc = " operation panics."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use crossbeam_utils::sync::ShardedLock;"] # [doc = ""] # [doc = " let lock = ShardedLock::new(1);"] # [doc = ""] # [doc = " let n = lock.read().unwrap();"] # [doc = " assert_eq!(*n, 1);"] # [doc = ""] # [doc = " assert!(lock.try_write().is_err());"] # [doc = " ```"] pub fn try_write (& self) -> TryLockResult < ShardedLockWriteGuard < '_ , T > > { let mut poisoned = false ; let mut blocked = None ; for (i , shard) in self . shards . iter () . enumerate () { let guard = match shard . lock . try_write () { Ok (guard) => guard , Err (TryLockError :: Poisoned (err)) => { poisoned = true ; err . into_inner () } Err (TryLockError :: WouldBlock) => { blocked = Some (i) ; break ; } } ; unsafe { let guard : RwLockWriteGuard < 'static , () > = mem :: transmute (guard) ; let dest : * mut _ = shard . write_guard . get () ; * dest = Some (guard) ; } } if let Some (i) = blocked { for shard in self . shards [0 .. i] . iter () . rev () { unsafe { let dest : * mut _ = shard . write_guard . get () ; let guard = (* dest) . take () ; drop (guard) ; } } Err (TryLockError :: WouldBlock) } else if poisoned { let guard = ShardedLockWriteGuard { lock : self , _marker : PhantomData , } ; Err (TryLockError :: Poisoned (PoisonError :: new (guard))) } else { Ok (ShardedLockWriteGuard { lock : self , _marker : PhantomData , }) } } # [doc = " Locks with exclusive write access, blocking the current thread until it can be acquired."] # [doc = ""] # [doc = " The calling thread will be blocked until there are no more writers which hold the lock."] # [doc = " There may be other readers currently inside the lock when this method returns. This method"] # [doc = " does not provide any guarantees with respect to the ordering of whether contentious readers"] # [doc = " or writers will acquire the lock first."] # [doc = ""] # [doc = " Returns a guard which will release the exclusive access when dropped."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method will return an error if the lock is poisoned. A lock gets poisoned when a write"] # [doc = " operation panics."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This method might panic when called if the lock is already held by the current thread."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use crossbeam_utils::sync::ShardedLock;"] # [doc = ""] # [doc = " let lock = ShardedLock::new(1);"] # [doc = ""] # [doc = " let mut n = lock.write().unwrap();"] # [doc = " *n = 2;"] # [doc = ""] # [doc = " assert!(lock.try_read().is_err());"] # [doc = " ```"] pub fn write (& self) -> LockResult < ShardedLockWriteGuard < '_ , T > > { let mut poisoned = false ; for shard in self . shards . iter () { let guard = match shard . lock . write () { Ok (guard) => guard , Err (err) => { poisoned = true ; err . into_inner () } } ; unsafe { let guard : RwLockWriteGuard < '_ , () > = guard ; let guard : RwLockWriteGuard < 'static , () > = mem :: transmute (guard) ; let dest : * mut _ = shard . write_guard . get () ; * dest = Some (guard) ; } } if poisoned { Err (PoisonError :: new (ShardedLockWriteGuard { lock : self , _marker : PhantomData , })) } else { Ok (ShardedLockWriteGuard { lock : self , _marker : PhantomData , }) } } }
